import{_ as a,o as i,c as o,a2 as n}from"./chunks/framework.CDpkVv68.js";const m=JSON.parse('{"title":"Tailoring","description":"","frontmatter":{},"headers":[],"relativePath":"es/game-design/professions/tailoring.md","filePath":"es/game-design/professions/tailoring.md"}'),s={name:"es/game-design/professions/tailoring.md"};function r(l,e,t,d,c,p){return i(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="tailoring" tabindex="-1">Tailoring <a class="header-anchor" href="#tailoring" aria-label="Enlace permanente a &quot;Tailoring&quot;">​</a></h1><p><strong>Estado del diseño:</strong> Propuesto; todas las mecánicas, ejemplos y vías de técnicas siguientes siguen siendo candidatos. <strong>Implementación:</strong> este batch documental no establece implementación de este rediseño. <strong>Disponibilidad:</strong> no establecida. <strong>Verificación:</strong> solo revisión documental; sin prueba de gameplay. <strong>Revisado:</strong> 2026-10-09 para la proyección pública; estado del diseño y mecánicas conservados de la especificación canónica.</p><p><a href="/Syrolands-Public/es/guide/professions/tailoring.html">Panorama para jugadores</a> · <a href="/Syrolands-Public/es/game-design/professions/profession-system.html">Sistema de profesiones</a></p><h2 id="purpose-and-profession-loop" tabindex="-1">Propósito y ciclo profesional <a class="header-anchor" href="#purpose-and-profession-loop" aria-label="Enlace permanente a &quot;Propósito y ciclo profesional&quot;">​</a></h2><p>Tailoring debería ser la profesión de materiales flexibles:</p><ul><li>pieles crudas;</li><li>cuero;</li><li>pieles con pelo;</li><li>tela;</li><li>fibras;</li><li>hilo;</li><li>acolchado;</li><li>costuras;</li><li>armadura flexible;</li><li>prendas;</li><li>aislamiento;</li><li>ajuste;</li><li>tratamientos textiles.</li></ul><p>Desollar no debería ser necesariamente una habilidad independiente. Sinergia potencial:</p><ul><li>Tailoring -&gt; conservar/procesar pieles;</li><li>Anatomy -&gt; dónde/cómo cortar;</li><li>Animal Lore -&gt; conocimiento específico de criaturas.</li></ul><p>Los cadáveres de criaturas pueden proporcionar distintas zonas/componentes materiales. El método de daño puede afectar la calidad de la piel:</p><ul><li>los cortes pueden dañarla;</li><li>el fuego puede quemarla;</li><li>el daño contundente puede preservar mejor la superficie;</li></ul><p>etc.</p><h3 id="core-chain" tabindex="-1">Cadena principal <a class="header-anchor" href="#core-chain" aria-label="Enlace permanente a &quot;Cadena principal&quot;">​</a></h3><p>Recolectar -&gt; Conservar -&gt; Procesar -&gt; Clasificar -&gt; Cortar -&gt; Montar -&gt; Ajustar -&gt; Acabar</p><h3 id="leather-processing-may-include" tabindex="-1">El procesamiento de cuero puede incluir <a class="header-anchor" href="#leather-processing-may-include" aria-label="Enlace permanente a &quot;El procesamiento de cuero puede incluir&quot;">​</a></h3><ul><li>limpieza;</li><li>curado;</li><li>curtido;</li><li>tratamiento.</li></ul><p>Métodos distintos de curtido/tratamiento pueden crear identidades materiales diferentes:</p><ul><li>más firme/duradero;</li><li>más suave/flexible;</li><li>resistente a la intemperie;</li><li>tratado alquímicamente.</li></ul><h3 id="fibers-cloth" tabindex="-1">Fibras/tela <a class="header-anchor" href="#fibers-cloth" aria-label="Enlace permanente a &quot;Fibras/tela&quot;">​</a></h3><ul><li>lino;</li><li>algodón;</li><li>lana;</li><li>seda;</li><li>cáñamo;</li><li>fibras fantásticas posteriormente.</li></ul><p>Identidades posibles de tejido:</p><ul><li>suelto;</li><li>denso;</li><li>en capas;</li><li>reforzado.</li></ul><p>La construcción de armaduras/ropa puede usar capas conceptualmente:</p><ul><li>exterior;</li><li>estructural;</li><li>acolchado;</li><li>forro.</li></ul><p>La armadura de tela/cuero puede proteger significativamente sin actuar como placas.</p><h3 id="field-utility" tabindex="-1">Utilidad en el terreno <a class="header-anchor" href="#field-utility" aria-label="Enlace permanente a &quot;Utilidad en el terreno&quot;">​</a></h3><ul><li>ajuste;</li><li>costuras de campaña;</li><li>reparación;</li><li>evaluación de materiales;</li><li>penalizaciones reducidas mediante ajuste/mantenimiento correctos en vez de +Armor fijo.</li></ul><h3 id="fashion-and-status" tabindex="-1">Moda y estatus <a class="header-anchor" href="#fashion-and-status" aria-label="Enlace permanente a &quot;Moda y estatus&quot;">​</a></h3><ul><li>cortes;</li><li>patrones;</li><li>ribetes;</li><li>tintes;</li><li>bordados;</li><li>estilos de gremios/culturales.</li></ul><p>Los tintes pueden conectar eventualmente con pigmentos, mordientes y Alchemy, pero mantener controlada la complejidad inicial.</p><h2 id="knowledge-and-specialization" tabindex="-1">Conocimiento y especialización <a class="header-anchor" href="#knowledge-and-specialization" aria-label="Enlace permanente a &quot;Conocimiento y especialización&quot;">​</a></h2><p><strong>Material/Tailoring Journal.</strong> Aprender zonas materiales, conservación, procesamiento, cortes y construcción. El ajuste funcional y la moda/estatus son direcciones legítimas de especialización.</p><h2 id="shared-progression-production-and-economy" tabindex="-1">Progresión, producción y economía compartidas <a class="header-anchor" href="#shared-progression-production-and-economy" aria-label="Enlace permanente a &quot;Progresión, producción y economía compartidas&quot;">​</a></h2><p>El <a href="/Syrolands-Public/es/game-design/characters/skills-and-skillcap.html">marco de habilidades del personaje</a> define enseñanza y dirección de límite/progreso. El <a href="/Syrolands-Public/es/game-design/professions/profession-system.html">Sistema de profesiones</a> define descubrimiento artesanal, conocimiento compartido, dominio manual, producción por lotes, encargos y reputación multidimensional. Esas reglas no se redefinen aquí de forma independiente. La <a href="/Syrolands-Public/es/game-design/items/itemization-and-craft-quality.html">especificación de calidad</a> define los límites compartidos de resultados y las propiedades raras de objetos.</p><h2 id="related-skills-and-field-interactions" tabindex="-1">Habilidades relacionadas e interacciones en el terreno <a class="header-anchor" href="#related-skills-and-field-interactions" aria-label="Enlace permanente a &quot;Habilidades relacionadas e interacciones en el terreno&quot;">​</a></h2><p>Anatomy puede informar de cómo/dónde cortar; Animal Lore puede orientar recolección específica de criaturas; Tailoring conserva y procesa la piel. Alchemy puede aportar tratamientos, pigmentos y mordientes. Estas funciones propuestas no redefinen las comprobaciones actuales de Anatomy.</p><p><a href="/Syrolands-Public/es/game-design/creatures.html">Anatomía de criaturas</a> · <a href="/Syrolands-Public/es/game-design/skills-and-knowledge.html">Anatomy y funciones de habilidades</a> · <a href="/Syrolands-Public/es/game-design/professions/alchemy.html">Alchemy</a> · <a href="/Syrolands-Public/es/game-design/equipment-and-loot.html">Equipo y botín</a>.</p><h2 id="abstraction-and-technical-boundary" tabindex="-1">Abstracción y límite técnico <a class="header-anchor" href="#abstraction-and-technical-boundary" aria-label="Enlace permanente a &quot;Abstracción y límite técnico&quot;">​</a></h2><p>Conservar solo estado e información que apoyen decisiones significativas. Se aplican las <a href="/Syrolands-Public/es/game-design/professions/profession-system.html#performance-abstraction-and-authority">restricciones compartidas de abstracción/autoridad</a> y la arquitectura del mundo vivo; la persistencia requiere un diseño técnico separado. Aquí no se eligen identificadores de paquetes, esquemas, temporizadores, recursos de interfaz ni algoritmos de ejecución.</p><h2 id="open-questions" tabindex="-1">Preguntas abiertas <a class="header-anchor" href="#open-questions" aria-label="Enlace permanente a &quot;Preguntas abiertas&quot;">​</a></h2><p>Si hace falta una habilidad separada de desuello; rendimiento por zona del cadáver e historial de daño; duración de conservación/curtido; contrapartidas de ajuste y protección; capas visuales frente a funcionales; complejidad de tintes y costes de mantenimiento. Las capas conceptuales no establecen soporte arbitrario de sprites/equipo heredados.</p><p>El <a href="/Syrolands-Public/es/game-design/professions/profession-system.html#open-questions-and-reconciliation-required">registro compartido de conciliación</a> define los conflictos entre sistemas. Los experimentos y la evidencia de combate existentes no validan este rediseño de profesiones.</p>',41)])])}const h=a(s,[["render",r]]);export{m as __pageData,h as default};
